import os
import glob
from pathlib import Path

# 找尋 /tmp 底下的多媒體檔案
extensions = ['.wav', '.mp3', '.mp4', '.png']
media_files = []

for ext in extensions:
    # 遞迴搜尋所有符合副檔名的檔案
